def main():
 for path in (ROOT/'help').glob('*.html'):
  lang=path.stem;catalog=json.loads((ROOT/'languages'/f'{lang}.json').read_text());text=path.read_text()
  text=re.sub(r'<!-- illustrated:start -->.*?<!-- illustrated:end -->','',text,flags=re.S)
  def section(m):
   block=m.group(0);entry=re.search(r'data-menu="([^"]+)"',block).group(1);key=entry.split('/')[-1]
   if key=='settings':block=re.sub(r'<p>.*?</p>','<p>'+E(catalog['download_hint'])+'</p>',block,count=1,flags=re.S)
   if key=='lookup':block=re.sub(r'<p>.*?</p>','<p>'+E(catalog['lookup_hint_joker' if 'game_joker' in entry else 'lookup_hint_lotto'])+'</p>',block,count=1,flags=re.S)
   extra='<div class="illustrated">'
   # Nicht bildlich vorgeben, einen Systemdialog aufgenommen zu haben.
   images=[] if key in ('quit','db_backup','local_import','recovery_choose','logs','manual','tip_save','tip_print') else pictures(entry)
   if images:extra+='<p class="caption">'+E(NOTES[lang])+'</p>'
   for image in images:
    if not (ROOT/'help/images'/f'{image}.png').exists():raise FileNotFoundError(image)
    extra+=f'<figure><a href="images/{image}.png"><img loading="lazy" src="images/{image}.png" alt="{E(catalog.get(key,key))} — {E(NOTES[lang])}"></a><figcaption>{E(catalog.get(key,key))}</figcaption></figure>'
   if key.startswith('s_'):
    extra+='<p>'+E(catalog.get('s_hint_'+key[2:],''))+'</p>'
   if key=='s_charts':
    extra+='<table>'
    for chart in ('frequency','pause','timeline','sums','parity','low_high','heatmap','deviation','rolling','zscore'):
     extra+='<tr><th>'+E(catalog['s_chart_'+chart])+'</th><td>'+E(catalog['s_chart_hint_'+chart])+'</td></tr>'
    extra+='</table><p>'+E(catalog['chart_number_help'])+'</p>'
    for chart in ('frequency','pause','timeline','sums','parity','low_high','heatmap','deviation','rolling','zscore'):
     extra+=f'<figure><a href="images/chart-{chart}.png"><img loading="lazy" src="images/chart-{chart}.png" alt="{E(catalog["s_chart_"+chart])}"></a><figcaption>{E(catalog["s_chart_hint_"+chart])}</figcaption></figure>'
   if lang in ('de','en',*TRANSLATIONS):
    rows=list(DETAILS.get(key,[]))
    if key.startswith('s_'):rows+=STATS
    if key=='tip_create':rows+=TIPS
    elif key.startswith('tip_'):rows+=TIPS[3:]
    elif entry.startswith('profile/'):rows+=TIPS[1:2]
    if key in ('history','lookup','quotes','tip_history') or key.startswith('s_'):rows.append(NAV)
    if rows:extra+=table(rows,lang)
    if key.startswith('s_') or key=='tip_create':
     game='joker' if 'game_joker' in entry else 'lotto';kind=key[2:] if key.startswith('s_') else None
     keys=[k for k in (*DEFAULTS[game],'weight') if kind is None or ('joker' if k=='weight' else 'patterns')==kind] if game=='joker' else [k for k in (*DEFAULTS[game],'weight') if kind is None or PAGES[k]==kind]
     if keys:
      extra+='<h4>'+('Regelwerte im Einzelnen' if lang=='de' else tr('Individual rule values',lang))+'</h4><table><tr><th>'+('Option' if lang=='de' else tr('Option',lang))+'</th><th>'+('Standard / Bereich' if lang=='de' else tr('Default / range',lang))+'</th><th>'+('Auswirkung' if lang=='de' else tr('Effect',lang))+'</th></tr>'
      for k in keys:
       default=DEFAULTS[game].get(k,1.0);bound,de,en=RULES[k]
       extra+='<tr><th>'+E(catalog['tip_weight' if k=='weight' else 'rule_'+k])+'</th><td>'+E(str(default))+' / '+E(bound)+'</td><td>'+E(de if lang=='de' else tr(en,lang))+'</td></tr>'
      extra+='</table>'
   extra+='</div>'
   return block.replace('</section>','<!-- illustrated:start -->'+extra+'<!-- illustrated:end --></section>')
  text=re.sub(r'<section\b[^>]*data-menu="[^"]+"[^>]*>.*?</section>',section,text,flags=re.S)
  style='''<style id="illustrated-style">body{max-width:1200px;margin:2rem auto;padding:0 1rem;font:17px/1.6 system-ui,sans-serif}section{margin:2rem 0;padding-top:1rem;border-top:1px solid #aaa}img{display:block;max-width:100%;height:auto}figure{margin:1.5rem 0}table{border-collapse:collapse;width:100%;margin:1rem 0}td,th{border:1px solid #aaa;padding:.65rem;text-align:start;vertical-align:top;overflow-wrap:anywhere}th{font-weight:600;min-width:9rem}figcaption,.caption{font-size:.9rem}nav ul{columns:2}a{overflow-wrap:anywhere}@media(max-width:700px){nav ul{columns:1}table{display:block;overflow-x:auto}}@media print{nav{break-after:page}figure{break-inside:avoid}img{max-height:20cm;object-fit:contain}}</style>'''
  text=re.sub(r'<style id="illustrated-style">.*?</style>','',text,flags=re.S).replace('<body',style+'<body',1)
  text=re.sub(r'1\.0\.(?:26|27)',VERSION,text);path.write_text(text)
 print('Illustrated help updated for 10 languages; detailed control reference: all 10 languages.')
